'use strict';
(()=>{
  const el=id=>document.getElementById(id),panel=document.createElement('section');panel.id='message-controller';panel.className='message-controller glass-sheet';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','iMessage controller');
  panel.innerHTML=`<header><strong>iMessage controller</strong><button id="controller-close" aria-label="Close controller">${icon('close')}</button></header><p id="controller-state">Local tester · iMessage not connected</p><form id="controller-test"><label for="controller-command">Try a command on this widget</label><div><input id="controller-command" placeholder="feed add example.com/blog" maxlength="2000" autocomplete="off"><button type="submit">Run</button></div></form><output id="controller-result" aria-live="polite">Try help to see available commands.</output><details><summary>Connect iMessage</summary><p>Keep the desktop app open. Only your configured sender and conversation can control it. Results appear here; the Photon adapter can reply in iMessage.</p><label for="controller-provider">Provider</label><select id="controller-provider"><option value="bluebubbles">BlueBubbles · on your Mac</option><option value="photon">Photon · Spectrum Stable adapter</option></select><label for="controller-sender">Allowed sender address / ID</label><input id="controller-sender" placeholder="+15551234567" autocomplete="off"><label for="controller-chat">Allowed conversation ID</label><input id="controller-chat" placeholder="Exact chat GUID / Spectrum space ID" autocomplete="off"><label class="controller-own"><input id="controller-own" type="checkbox"> BlueBubbles: allow my own sent messages</label><small>For the same Apple ID, enable this and prefix commands with “open sesame”. The conversation must still match.</small><div class="controller-actions"><button id="controller-start">Start receiver</button><button id="controller-stop" disabled>Stop</button></div><textarea id="controller-endpoint" readonly aria-label="Local connection details" hidden></textarea><small id="controller-setup">BlueBubbles: add the receiver URL as a new-message webhook on this Mac. Photon: run desktop/photon-controller.mjs from the source download with your Stable project credentials and the receiver details. This web preview cannot receive iMessages.</small><a href="downloads/open-sesame-desktop-source.zip" download>Desktop source & setup ${icon('download')}</a><a id="controller-docs" href="https://docs.bluebubbles.app/server/developer-guides/rest-api-and-webhooks" target="_blank" rel="noopener noreferrer">Provider documentation ${icon('arrow-up-right')}</a></details>`;
  el('widget-panel').append(panel);let receiver=false,busy=false,lastFocus=null,background=[];
  const help='feed add <site> · feed follow <RSS URL> · feeds · feed pause/resume/refresh <exact name or URL> · note/task/bookmark <text> · focus 25 / focus pause · open reading/items/agents/lockin · size small/medium/large/max · status';
  async function execute(raw,id=''){
    const c=OpenSesameControllerModel.parse(raw);
    if(c.action==='help')return help;
    if(c.action==='status')return `${activeItems().length} active items · ${openSesameReading.listFeeds().length} feeds · ${state.size} · ${focusRunning?'Focus running':'Focus paused'}`;
    if(c.action==='feeds')return openSesameReading.listFeeds().map(f=>f.title+' — '+f.url+(f.paused?' [paused]':'')).join('\n')||'No feeds yet. Try feed add <site>.';
    if(c.action==='feed.add')return openSesameReading.addFeed(c.url,c.site);
    if(c.action.startsWith('feed.'))return openSesameReading.manageFeed(c.action.slice(5),c.name);
    if(c.action==='open'){changeScenario(c.tab);return 'Opened '+c.tab}
    if(c.action==='size'){state.size=c.size;render();return 'Size: '+c.size}
    if(c.action==='focus'){
      if(c.value==='pause'){if(focusRunning)el('focus-start').click();return 'Focus paused'}
      const minutes=Number(c.value);if(!focusTopics.length)throw Error('Add a topic to your focus plan first.');if(focusRunning){if(focusMinutes===minutes)return 'Focus is already running';throw Error('Pause the current focus period before changing it.')}
      if(focusTopics.length>topicLimit(minutes))throw Error('This focus plan has too many topics for that period.');setFocusDuration(minutes);el('focus-start').click();return 'Started '+minutes+' minutes of focus';
    }
    if(c.action==='capture'){
      const key=id?'controller:'+id:newId();if(items.some(n=>n.id===key))return 'Already saved';
      if(activeItems().length>=30||items.length>=300)throw Error('Items is full. Archive active items or remove archived items first.');
      const url=c.kind==='bookmark'?pageUrl(c.text):'';if(c.kind==='bookmark'&&!url)throw Error('Use one bookmark URL per message.');
      const item={id:key,kind:c.kind,text:c.text,url,title:'',body:'',projectId:'',done:false};items.push(item);if(!(await saveItems())){items.pop();throw Error('Could not save; device storage is full.')}renderItems();renderCompact();return 'Saved '+c.kind+' to Inbox';
    }
  }
  function close(){panel.hidden=true;background.forEach(([n,inert])=>n.inert=inert);background=[];lastFocus?.focus({preventScroll:true})}
  el('reading-controller-open').addEventListener('click',async ()=>{lastFocus=document.activeElement;background=[...el('widget-panel').children].filter(n=>n!==panel).map(n=>[n,n.inert]);background.forEach(([n])=>n.inert=true);panel.hidden=false;el('controller-command').focus()});el('controller-close').addEventListener('click',close);
  panel.addEventListener('keydown',async e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}if(e.key==='Tab'){const fields=[...panel.querySelectorAll('button,input,select,textarea,a,summary')].filter(n=>!n.disabled&&n.getClientRects().length),first=fields[0],last=fields.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  el('controller-test').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;try{el('controller-result').textContent=await execute(el('controller-command').value)}catch(error){el('controller-result').textContent=error.message}finally{busy=false}});
  function stateLabel(info){receiver=!!info.running;el('controller-state').textContent=receiver?'Receiver ready · '+info.provider+' · awaiting allowed messages':'Local tester · iMessage not connected';el('controller-start').disabled=receiver;el('controller-stop').disabled=!receiver;el('controller-endpoint').hidden=!receiver;el('controller-endpoint').value=receiver?info.endpoint+(info.token?'\nOPEN_SESAME_CONTROLLER_TOKEN='+info.token:''):''}
  el('controller-provider').addEventListener('change',async ()=>el('controller-docs').href=el('controller-provider').value==='photon'?'https://photon.codes/docs/spectrum-ts/getting-started':'https://docs.bluebubbles.app/server/developer-guides/rest-api-and-webhooks');
  el('controller-start').addEventListener('click',async()=>{try{await openSesameBridge.ready;if(!openSesameBridge.available)throw Error('Open the desktop companion to start a receiver. You can test commands locally here.');stateLabel(await openSesameBridge.request('controller.start',{provider:el('controller-provider').value,sender:el('controller-sender').value.trim(),chat:el('controller-chat').value.trim(),allowSelf:el('controller-own').checked}));el('controller-result').textContent='Receiver started. Configure the provider using the connection details below.'}catch(error){el('controller-result').textContent=error.message}});
  el('controller-stop').addEventListener('click',async()=>{try{stateLabel(await openSesameBridge.request('controller.stop'))}catch(error){el('controller-result').textContent=error.message}});
  setInterval(async()=>{if(!receiver||busy||!openSesameBridge.available)return;busy=true;try{const event=await openSesameBridge.request('controller.poll');if(event){let result;try{result=await execute(event.text,event.id)}catch(error){result='Could not apply command: '+error.message}el('controller-result').textContent=result;await openSesameBridge.request('controller.ack',{id:event.id,result})}}catch(error){el('controller-result').textContent=error.message}finally{busy=false}},2000);
  window.addEventListener('open-sesame-desktop-disconnected',async ()=>stateLabel({running:false}));window.OpenSesameController={execute};
})();
